<?php
require __DIR__.'/bootstrap.php';require_perm('invoices.view');$me=user();$branch=is_admin()?null:require_branch();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();require_perm('invoices.create');$id=(int)($_POST['id']??0);
if(isset($_POST['create'])){$descriptions=$_POST['item_description']??[];$kgs=$_POST['item_kg']??[];$rates=$_POST['item_rate']??[];$items=[];$total=0;foreach($descriptions as $i=>$description){$description=trim($description);$kg=(float)($kgs[$i]??0);$rate=(float)($rates[$i]??0);if($description===''||$kg<=0||$rate<=0){flash('danger','Every item needs a description, KG, and rate greater than zero.');redirect('general_invoices.php');}$amount=round($kg*$rate,2);$items[]=[$description,$kg,$rate,$amount];$total+=$amount;}if(!$items){flash('danger','Add at least one invoice item.');redirect('general_invoices.php');}$invoiceNo='GINV-'.date('Y').'-'.str_pad((string)(1+(int)$pdo->query('SELECT COUNT(*) FROM general_invoices')->fetchColumn()),5,'0',STR_PAD_LEFT);$invoiceBranch=$branch??(int)$_POST['branch_id'];$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO general_invoices(invoice_no,receiver,phone,description,kg,rate,amount,issue_date,due_date,status,notes,branch_id,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$invoiceNo,trim($_POST['receiver']),trim($_POST['phone']),$items[0][0],$items[0][1],$items[0][2],$total,$_POST['issue_date'],$_POST['due_date'],'Issued',trim($_POST['notes']),$invoiceBranch,$me['id']]);$invoiceId=(int)$pdo->lastInsertId();$add=$pdo->prepare('INSERT INTO general_invoice_items(general_invoice_id,description,kg,rate,amount) VALUES(?,?,?,?,?)');foreach($items as $item)$add->execute([$invoiceId,...$item]);$pdo->commit();flash('success',"General invoice $invoiceNo created.");}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Invoice could not be created.');}}
elseif(isset($_POST['delete'])){$find=$pdo->prepare('SELECT id FROM general_invoices WHERE id=?'.($branch===null?'':' AND branch_id='.(int)$branch));$find->execute([$id]);if(!$find->fetch()){flash('danger','Invoice not found.');}else{$pdo->beginTransaction();try{$pdo->prepare('DELETE FROM general_invoices WHERE id=?')->execute([$id]);$pdo->commit();flash('success','Invoice deleted.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Invoice could not be deleted.');}}}
elseif(isset($_POST['status'])){$status=$_POST['status'];if(!in_array($status,['Paid','Cancelled'],true)){flash('danger','Invalid invoice status.');redirect('general_invoices.php');}$find=$pdo->prepare('SELECT * FROM general_invoices WHERE id=?'.($branch===null?'':' AND branch_id='.(int)$branch));$find->execute([$id]);$invoice=$find->fetch();if(!$invoice){flash('danger','Invoice not found.');redirect('general_invoices.php');}$pdo->beginTransaction();try{$pdo->prepare('UPDATE general_invoices SET status=? WHERE id=?')->execute([$status,$id]);if($status==='Paid'&&$invoice['status']!=='Paid')$pdo->prepare("INSERT INTO payments(general_invoice_id,amount,location,payment_method,reference_no,notes,received_by,paid_at) VALUES(?,?,?,'Other',?,?,?,NOW())")->execute([$id,$invoice['amount'],'MGQ','GINV-'.$invoice['invoice_no'],'Automatically recorded when the general invoice was marked paid.',$me['id']]);$pdo->commit();flash('success',$status==='Paid'?'Invoice marked paid and payment added.':'Invoice cancelled.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Invoice could not be updated.');}}
redirect('general_invoices.php');}
$pdo->exec("UPDATE general_invoices SET status='Overdue' WHERE status='Issued' AND due_date<CURDATE()".($branch===null?'':' AND branch_id='.(int)$branch));$rows=$pdo->query('SELECT g.*,b.name branch_name,COALESCE(SUM(p.amount),0) paid_amount FROM general_invoices g JOIN branches b ON b.id=g.branch_id LEFT JOIN payments p ON p.general_invoice_id=g.id'.($branch===null?'':' WHERE g.branch_id='.(int)$branch).' GROUP BY g.id ORDER BY g.issue_date DESC,g.id DESC')->fetchAll();$branches=is_admin()?$pdo->query('SELECT id,name,code FROM branches WHERE active=1 ORDER BY name')->fetchAll():[];$title='General invoices';require __DIR__.'/partials/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-center mb-4"><div><h1 class="h3 fw-bold mb-1">General invoices</h1><p class="text-secondary mb-0">Create professional invoices for services not linked to a shipment.</p></div><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#generalInvoice"><i class="bi bi-plus-lg"></i> Create invoice</button></div>
<div class="card border-0 shadow-sm p-3 p-lg-4"><input class="form-control mb-3" style="max-width:460px" data-table-search placeholder="Search invoice, customer, phone, or branch"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Invoice</th><th>Customer</th><th>Issued / Due</th><th>Total Amount</th><th>Paid Money</th><th>Balance Due</th><th>Status</th><?php if(is_admin()):?><th>Branch</th><?php endif?><th></th></tr></thead><tbody><?php foreach($rows as $r):$balance=max(0,(float)$r['amount']-(float)$r['paid_amount']);?><tr><td class="fw-bold text-primary"><?=e($r['invoice_no'])?></td><td><?=e($r['receiver'])?><small class="d-block text-secondary"><?=e($r['phone']?:'—')?></small></td><td><?=app_date($r['issue_date'])?><small class="d-block text-secondary">Due <?=app_date($r['due_date'])?></small></td><td class="fw-semibold"><?=money($r['amount'])?></td><td class="text-success fw-semibold"><?=money($r['paid_amount'])?></td><td class="text-danger fw-bold"><?=money($balance)?></td><td><span class="status status-<?=strtolower(str_replace(' ','-',$r['status']))?>"><?=e($r['status'])?></span></td><?php if(is_admin()):?><td><?=e($r['branch_name'])?></td><?php endif?><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" target="_blank" href="general_invoice_print.php?id=<?=$r['id']?>"><i class="bi bi-printer"></i> Print</a><a class="btn btn-sm btn-outline-secondary" href="general_invoice_edit.php?id=<?=$r['id']?>"><i class="bi bi-pencil"></i> Edit</a><?php if(!in_array($r['status'],['Paid','Cancelled'],true)):?><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-success" name="status" value="Paid">Paid</button></form><?php endif?><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger" name="delete" data-confirm="Delete this invoice?">Delete</button></form></td></tr><?php endforeach?></tbody></table></div></div>
<div class="modal fade" id="generalInvoice"><div class="modal-dialog modal-lg"><form method="post" class="modal-content"><div class="modal-header bg-primary text-white"><h2 class="h5 mb-0">Create general invoice</h2><button class="btn-close btn-close-white" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="row"><div class="col-md-7"><label class="form-label">Receiver / customer</label><input class="form-control mb-3" name="receiver" required></div><div class="col-md-5"><label class="form-label">Phone</label><input class="form-control mb-3" name="phone"></div></div><?php if(is_admin()):?><label class="form-label">Branch</label><select class="form-select mb-3" name="branch_id"><?php foreach($branches as $b):?><option value="<?=$b['id']?>"><?=e($b['name'].' ('.$b['code'].')')?></option><?php endforeach?></select><?php endif?><div class="d-flex justify-content-between align-items-center"><h3 class="h6 mb-2">Invoice items</h3><button id="addItem" type="button" class="btn btn-sm btn-outline-primary"><i class="bi bi-plus"></i> Add item</button></div><div class="table-responsive"><table class="table table-sm" id="itemsTable"><thead><tr><th>Description</th><th style="width:130px">KG</th><th style="width:150px">Rate</th><th style="width:140px">Amount</th><th></th></tr></thead><tbody><tr><td><input class="form-control" name="item_description[]" required></td><td><input class="form-control item-kg" type="number" min=".01" step=".01" name="item_kg[]" required></td><td><input class="form-control item-rate" type="number" min=".01" step=".01" name="item_rate[]" required></td><td class="item-amount fw-semibold">0.00</td><td><button type="button" class="btn btn-sm btn-outline-danger remove-item"><i class="bi bi-trash"></i></button></td></tr></tbody><tfoot><tr><th colspan="3" class="text-end">Total Amount</th><th id="invoiceTotal" class="text-primary fs-6">0.00</th><th></th></tr></tfoot></table></div><div class="row"><div class="col"><label class="form-label">Issue date</label><input class="form-control" type="date" name="issue_date" value="<?=date('Y-m-d')?>" required></div><div class="col"><label class="form-label">Due date</label><input class="form-control" type="date" name="due_date" value="<?=date('Y-m-d',strtotime('+14 days'))?>" required></div></div><label class="form-label mt-3">Notes</label><textarea class="form-control" name="notes"></textarea></div><div class="modal-footer"><button class="btn btn-primary px-4" name="create">Create invoice</button></div></form></div></div>
<script>const body=document.querySelector('#itemsTable tbody'),add=document.querySelector('#addItem');const row=()=>`<tr><td><input class="form-control" name="item_description[]" required></td><td><input class="form-control item-kg" type="number" min=".01" step=".01" name="item_kg[]" required></td><td><input class="form-control item-rate" type="number" min=".01" step=".01" name="item_rate[]" required></td><td class="item-amount fw-semibold">0.00</td><td><button type="button" class="btn btn-sm btn-outline-danger remove-item"><i class="bi bi-trash"></i></button></td></tr>`;function totals(){let total=0;body.querySelectorAll('tr').forEach(r=>{const x=(parseFloat(r.querySelector('.item-kg').value)||0)*(parseFloat(r.querySelector('.item-rate').value)||0);r.querySelector('.item-amount').textContent=x.toFixed(2);total+=x});document.querySelector('#invoiceTotal').textContent=total.toFixed(2)}add.onclick=()=>{body.insertAdjacentHTML('beforeend',row());totals()};body.addEventListener('input',totals);body.addEventListener('click',e=>{if(e.target.closest('.remove-item')&&body.rows.length>1){e.target.closest('tr').remove();totals()}});</script>
